  ('PROJ26-RIO-DOCE', 'Projetos — PES Rio Doce AgSUS/FUNASA (114/2026; sem critério étnico)', $modelo${"schema":1,"modelo":"PROJ26-RIO-DOCE","titulo_etapa":"Avaliação Documental e de Títulos","edital_rotulo":"","casas_parecer":1,"provisoria":{"eliminacao_automatica":[{"codigo":"CANCELADO","coluna":"SITUAÇÃO","quando":["CANCELADO"],"motivo":"Cancelou a inscrição"},{"codigo":"QUESTIONARIO","coluna_prefixo":"SITUAÇÃO - ","exceto":["FINALIZADO"],"motivo":"Não finalizou o questionário"},{"codigo":"REPROVADO_EMPREGARE","coluna":"REPROVADO","quando":["SIM"],"motivo":"Reprovado na Empregare"}],"nota_declarada":[],"divergencia_tolerancia":0,"desempate":["IDOSO","MAIOR_IDADE"]},"lote":{"base":"NOTA_MINIMA","nota_minima":10,"item_edital":"8.2.6","multiplo":null,"fixo":null,"inclui_cr":true,"por_modalidade":false,"inclui_empatados":true,"linha_anda":false,"publica_reposicao":false},"distribuicao":{"modo":"PEGAR_PROXIMO","criterio":"PARTES_IGUAIS","limite_por_analista":null,"novos":"MENOS_PENDENTES","dias_parada":3},"revisao":{"amostra_percentual":10,"minimo_por_analista":0,"todas":false,"inaptos_requisito":true,"inaptos_nota":false,"divergencia_pontos":null,"sinais":[],"entrou_pela_linha":false,"duplo_cego":false},"blocos":[{"codigo":"IDENTIDADE","titulo":"Documento de identificação oficial com foto","item_edital":"6.5","tipo":"DOCUMENTO","perguntas":[],"efeitos":{"NAO_CONFORME":"ELIMINA","NAO_ENVIADO":"ELIMINA"},"motivos":[{"codigo":"NAO_ACEITO","texto":"Documento de identificação fora da lista do subitem 6.5 (ex.: certidão, CPF, título de eleitor, carteira de estudante).","item_edital":"6.5.1","efeito":"ELIMINA"},{"codigo":"ILEGIVEL","texto":"Documento de identificação ilegível, não identificável ou danificado.","item_edital":"6.5.1","efeito":"ELIMINA"}]},{"codigo":"ESCOLARIDADE","titulo":"Formação exigida pela vaga (diploma ou certificado, frente e verso)","item_edital":"8.2.1","tipo":"DOCUMENTO","perguntas":[],"efeitos":{"NAO_CONFORME":"ELIMINA","NAO_ENVIADO":"ELIMINA"},"mo