abaixo de 40h ou de eventos não foram contabilizados."},{"codigo":"MOTORISTA_UMCQA","rotulo":"Motorista D: capacitação UMCQA","item_edital":"8.2.6","texto":"Cargo 15 (Motorista categoria D): o certificado de capacitação ou treinamento para condução, manejo e operação de UMCQA vale 5 pontos em cursos de aperfeiçoamento (máximo de 15 pontos para o cargo), conforme o subitem 8.2.6."}]}$modelo$::jsonb)
on conflict ("CO_MODELO") do update
   set "NO_MODELO" = excluded."NO_MODELO", "DS_CONFIGURACAO" = excluded."DS_CONFIGURACAO", "ST_ATIVO" = 'S', "DT_ATUALIZACAO" = now();

do $$
declare
  v_modelo record;
begin
  for v_modelo in
    select * from public."TB_REGRA_ANALISE_MODELO" where "CO_MODELO" in ('PROJ26-RIO-DOCE')
  loop
    perform private."FC_VALIDAR_REGRA_ANALISE"(v_modelo."DS_CONFIGURACAO");
  end loop;
end;
$$;

select "CO_MODELO", "NO_MODELO", jsonb_array_length("DS_CONFIGURACAO" -> 'blocos') as blocos
  from public."TB_REGRA_ANALISE_MODELO" where "CO_MODELO" in ('PROJ26-RIO-DOCE') order by 1;

commit;
